import { useEffect, useState } from 'react';

/**
 * Registers the service worker and reports when a new version of the app is
 * ready, **without ever installing it unprompted**.
 *
 * This is the whole reason the worker is hand-written rather than generated by
 * a plugin whose default is `skipWaiting`. Swapping the shell under someone who
 * is reading means their next navigation runs a different build than the one
 * they opened, and the failure mode is a blank page or a lost place — during
 * the exact activity the offline support exists to protect. So a waiting worker
 * sits and waits, and the reader is offered a reload.
 *
 * Nothing here runs in development: an installed worker serving a cached shell
 * is precisely what a dev server must not do, and debugging a stale worker
 * costs more time than the feature saves.
 */
export function useServiceWorker(): { updateReady: boolean; update: () => void } {
  const [waiting, setWaiting] = useState<ServiceWorker>();

  useEffect(() => {
    if (import.meta.env.DEV) return;
    if (!('serviceWorker' in navigator)) return;

    let cancelled = false;

    const watch = (registration: ServiceWorkerRegistration) => {
      if (cancelled) return;

      // A worker can already be waiting when the page loads — the reader may
      // have opened a tab, been given an update, and closed it again.
      if (registration.waiting) setWaiting(registration.waiting);

      registration.addEventListener('updatefound', () => {
        const installing = registration.installing;
        if (!installing) return;
        installing.addEventListener('statechange', () => {
          // `controller` distinguishes an update from the very first install.
          // Announcing "update available" to someone who has just arrived would
          // be both untrue and alarming.
          if (installing.state === 'installed' && navigator.serviceWorker.controller) {
            if (!cancelled) setWaiting(installing);
          }
        });
      });
    };

    // `import.meta.env.BASE_URL` rather than a literal: a project page is served
    // from `/<repo>/`, and a worker registered at the origin root would have a
    // scope wider than the app and would not be allowed to load from there.
    const url = `${import.meta.env.BASE_URL}sw.js`;
    navigator.serviceWorker
      .register(url, { scope: import.meta.env.BASE_URL })
      .then(watch)
      .catch(() => {
        // An unregistrable worker means no offline support, which is a
        // degradation and not a failure. The reader is told nothing, because
        // there is nothing they can do about it.
      });

    return () => {
      cancelled = true;
    };
  }, []);

  return {
    updateReady: waiting !== undefined,
    update: () => {
      if (!waiting) return;
      // Reload once the new worker has actually taken over, rather than
      // immediately: reloading first would just re-serve the old shell.
      navigator.serviceWorker.addEventListener('controllerchange', () => location.reload(), {
        once: true,
      });
      waiting.postMessage('SKIP_WAITING');
    },
  };
}
